import { readFileSync, writeFileSync } from 'node:fs'

const resource = new URL('../resources/leap-seconds.list', import.meta.url)
const target = new URL('../src/leap-seconds.generated.ts', import.meta.url)
const text = readFileSync(resource, 'utf8')

if (/[`\\\r]|\$\{/u.test(text))
  throw new Error('resources/leap-seconds.list needs escaping before it can be a template literal')

writeFileSync(
  target,
  '// Generated by scripts/embed-leap-seconds.mjs from resources/leap-seconds.list. Do not edit.\n' +
    `export const leapSecondsListText = \`${text}\`\n`,
)
